#include <iostream>
#include <unordered_map>
#include <vector>
#include <cstdint>

typedef uint64_t ul;
typedef long long ll;

const int MOD = 1000000007;

class Mint {
public:
    int val;
    Mint() : val(0) {}
    Mint(ll v) {
        v %= MOD;
        if (v < 0) v += MOD;
        val = (int)v;
    }
    Mint operator-() const { return Mint(-val); }
    Mint& operator+=(const Mint& o) {
        val += o.val;
        if (val >= MOD) val -= MOD;
        return *this;
    }
    Mint& operator-=(const Mint& o) {
        val -= o.val;
        if (val < 0) val += MOD;
        return *this;
    }
    Mint& operator*=(const Mint& o) {
        val = (ll)val * o.val % MOD;
        return *this;
    }
    friend Mint operator+(Mint a, const Mint& b) { return a += b; }
    friend Mint operator-(Mint a, const Mint& b) { return a -= b; }
    friend Mint operator*(Mint a, const Mint& b) { return a *= b; }
    friend Mint operator/(Mint a, const Mint& b) { return a *= inv(b); }
    static Mint inv(const Mint& a) {
        ll x, y;
        ll g = gcd_ext(a.val, MOD, x, y);
        if (g != 1) return Mint(0);
        return Mint(x);
    }
    static ll gcd_ext(ll a, ll b, ll& x, ll& y) {
        if (b == 0) { x = 1; y = 0; return a; }
        ll x1, y1;
        ll g = gcd_ext(b, a % b, x1, y1);
        x = y1;
        y = x1 - (a / b) * y1;
        return g;
    }
};

ul no[7];
int n;
Mint p[7][7];

ul po(int x) {
    return (ul)1 << x;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
    std::cin >> n;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int x;
            std::cin >> x;
            p[i][j] = Mint(x) / Mint(100);
        }
    }
    for (int i = 0; i < n; ++i) {
        no[i] = 0;
        for (int j = 0; j < (1 << n); ++j) {
            if (!((j >> i) & 1)) {
                no[i] |= po(j);
            }
        }
    }
    std::unordered_map<ul, Mint> cur;
    cur[1] = Mint(1);
    for (int i = 0; i < n; ++i) {
        std::unordered_map<ul, Mint> nxt;
        for (const auto& entry : cur) {
            ul state = entry.first;
            Mint prob = entry.second;
            for (int mask = 0; mask < (1 << n); ++mask) {
                ul new_state = 0;
                Mint new_prob = 1;
                for (int k = 0; k < n; ++k) {
                    if (mask & (1 << k)) {
                        new_prob *= p[i][k];
                        new_state |= (state & no[k]) << (1 << k);
                    } else {
                        new_prob *= Mint(1) - p[i][k];
                    }
                }
                nxt[new_state] += prob * new_prob;
            }
        }
        cur = std::move(nxt);
    }
    ul target = po((1 << n) - 1);
    std::cout << cur[target].val << '\n';
    return 0;
}
