import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 1000000007;

    static long modInv(long a) {
        long x, y;
        long g = gcdExt(a, MOD, x, y);
        if (g != 1) return 0;
        return (x % MOD + MOD) % MOD;
    }

    static long gcdExt(long a, long b, long x, long y) {
        if (b == 0) {
            x = 1;
            y = 0;
            return a;
        }
        long x1, y1;
        long g = gcdExt(b, a % b, x1, y1);
        x = y1;
        y = x1 - (a / b) * y1;
        return g;
    }

    static int modAdd(int a, int b) {
        int res = a + b;
        if (res >= MOD) res -= MOD;
        return res;
    }

    static int modSub(int a, int b) {
        int res = a - b;
        if (res < 0) res += MOD;
        return res;
    }

    static int modMul(int a, int b) {
        return (int)(((long)a * b) % MOD);
    }

    static long po(int x) {
        return 1L << x;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int[][] p = new int[n][n];
        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                int x = Integer.parseInt(st.nextToken());
                p[i][j] = (int)((x * modInv(100)) % MOD);
            }
        }

        long[] no = new long[7];
        for (int i = 0; i < n; i++) {
            no[i] = 0;
            for (int j = 0; j < (1 << n); j++) {
                if (((j >> i) & 1) == 0) {
                    no[i] |= po(j);
                }
            }
        }

        Map<Long, Integer> cur = new HashMap<>();
        cur.put(1L, 1);

        for (int i = 0; i < n; i++) {
            Map<Long, Integer> nxt = new HashMap<>();
            for (Map.Entry<Long, Integer> entry : cur.entrySet()) {
                long state = entry.getKey();
                int prob = entry.getValue();
                for (int mask = 0; mask < (1 << n); mask++) {
                    long newState = 0;
                    int newProb = 1;
                    for (int k = 0; k < n; k++) {
                        if ((mask & (1 << k)) != 0) {
                            newProb = modMul(newProb, p[i][k]);
                            newState |= ((state & no[k]) << (1 << k));
                        } else {
                            newProb = modMul(newProb, modSub(1, p[i][k]));
                        }
                    }
                    int nxtProb = modMul(prob, newProb);
                    nxt.merge(newState, nxtProb, (a, b) -> modAdd(a, b));
                }
            }
            cur = nxt;
        }

        long target = 1L << ((1 << n) - 1);
        System.out.println(cur.getOrDefault(target, 0));
    }
}
